$report = [ordered]@{purpose='Does AVX2 short-depthwise interior acceleration improve complete OCR latency without output or retained-memory changes?';timestamp=(Get-Date).ToString('o');git_head=(git -C $repo rev-parse HEAD).Trim();source_files=$sourceFiles;executable_sha256=$hash;source_stable=$true;aggregate_page_execution_seconds=$spent;execution_budget_seconds_per_version=60;process_deadline_seconds=15;cases=$execution}
[IO.File]::WriteAllText((Join-Path $PSScriptRoot "page-evidence-$VersionTag.json"),($report | ConvertTo-Json -Depth 100))

$ErrorActionPreference = 'Stop'
$execution=@()
foreach($variant in @('baseline','candidate-v1')) {
    $exe=if($variant -eq 'baseline') {Join-Path $PSScriptRoot 'baseline/profiling-tests.exe'} else {Join-Path $PSScriptRoot 'short-depthwise-tests.exe'}
    $out=Join-Path $PSScriptRoot "rec-diagnosis-$variant.log"
    if(Test-Path -LiteralPath $out) {throw 'Refuse to overwrite attribution'}
    $timer=[Diagnostics.Stopwatch]::StartNew()
    $process=Start-Process -FilePath $exe -ArgumentList @('runtime::optimized::tests::performance::recognition_backbone_physical_steps','--exact','--ignored','--nocapture','--test-threads=1') -WindowStyle Hidden -RedirectStandardOutput $out -RedirectStandardError "$out.stderr" -PassThru
    if(-not $process.WaitForExit(10000)) {Stop-Process -Id $process.Id -Force;throw 'Attribution timeout'}
    $process.WaitForExit();$timer.Stop()
    if($process.ExitCode -ne 0) {throw 'Attribution failed'}
    $text=[IO.File]::ReadAllText($out)
    $execution += [ordered]@{variant=$variant;exe_sha256=(Get-FileHash $exe).Hash;wall_seconds=$timer.Elapsed.TotalSeconds;output=$text}
    Write-Output $variant
    Get-Content $out | Select-String 'total_step_ms' | ForEach-Object {$_.Line}
}
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'rec-diagnosis.json'),($execution | ConvertTo-Json -Depth 5))

$ErrorActionPreference = 'Stop'
$repo = (Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
function Digest($path) { (Get-FileHash -LiteralPath $path).Hash.ToLowerInvariant() }
function Sources { @(git -C $repo ls-files --cached --others --exclude-standard src tools examples Cargo.toml Cargo.lock rust-toolchain.toml | Sort-Object -Unique | ForEach-Object { [ordered]@{path=$_;sha256=Digest (Join-Path $repo $_)} }) }
$sources = Sources
$sourceJson = $sources | ConvertTo-Json -Depth 5 -Compress
$baselineExe = Join-Path $PSScriptRoot 'baseline/cpu_owner_probe.exe'
$candidateExe = Join-Path $PSScriptRoot 'v2-pages.exe'
Copy-Item -LiteralPath (Join-Path $repo 'target/release/examples/cpu_owner_probe.exe') -Destination $candidateExe
$executables=@([ordered]@{variant='baseline';path=$baselineExe;sha256=Digest $baselineExe},[ordered]@{variant='v2';path=$candidateExe;sha256=Digest $candidateExe})
$cases=@(@('tiny','imgs_1',@('baseline','v2')),@('tiny','imgs_00018069',@('v2','baseline')),@('tiny','imgs_00006737',@('baseline','v2')),@('small','imgs_00018069',@('v2','baseline')),@('medium','imgs_00018069',@('baseline','v2')))
$spent=@{baseline=0.0;v2=0.0};$results=@()
foreach($case in $cases) {
    $measurements=@{}
    foreach($variant in $case[2]) {
        $exe=if($variant -eq 'baseline') {$baselineExe} else {$candidateExe}
        $stem=Join-Path $PSScriptRoot "final-$variant-$($case[0])-$($case[1])"
        if(Test-Path -LiteralPath "$stem.json") {throw 'Refuse to overwrite final comparison'}
        $timer=[Diagnostics.Stopwatch]::StartNew()
        $process=Start-Process -FilePath $exe -ArgumentList @($case[0],$case[1],'0','1') -WindowStyle Hidden -RedirectStandardOutput "$stem.json" -RedirectStandardError "$stem.log" -PassThru
        if(-not $process.WaitForExit(10000)) {Stop-Process -Id $process.Id -Force;throw 'Final comparison timeout'}
        $process.WaitForExit();$timer.Stop();$spent[$variant]+=$timer.Elapsed.TotalSeconds
        if($process.ExitCode -ne 0) {throw "Final comparison failed: $stem"}
        if($spent[$variant] -ge 35) {throw 'Final comparison exceeded bounded allocation'}
        $measurements[$variant]=[ordered]@{measurement=(Get-Content -LiteralPath "$stem.json" -Raw | ConvertFrom-Json);wall_seconds=$timer.Elapsed.TotalSeconds;stderr=[IO.File]::ReadAllText("$stem.log")}
    }
    $before=$measurements.baseline.measurement;$after=$measurements.v2.measurement
    foreach($field in @('pixel_sha256','manifest_sha256','control_output_sha256','recognized_lines','affinity','cpu_context_capacity')) {if($before.$field -ne $after.$field) {throw "Result/configuration mismatch: $field"}}
    foreach($field in @('retained_activation_bytes','retained_workspace_bytes','retained_kernel_scratch_bytes_subset_of_workspace','post_run_budgets')) {if($before.cases[0].$field -ne $after.cases[0].$field) {throw "Memory/budget mismatch: $field"}}
    $old=@($before.cases[0].samples_ms | Sort-Object)[1];$new=@($after.cases[0].samples_ms | Sort-Object)[1]
    $change=100*(1-$new/$old)
    $results += [ordered]@{model=$case[0];fixture=$case[1];execution_order=$case[2];baseline=$measurements.baseline;candidate=$measurements.v2;baseline_median_ms=$old;candidate_median_ms=$new;latency_reduction_percent=$change;complete_output_equal=$true;retained_bytes_equal=$true}
    Write-Output "$($case[0]) $($case[1]): $old -> $new ms; $([Math]::Round($change,2))% lower"
}
if($sourceJson -ne ((Sources) | ConvertTo-Json -Depth 5 -Compress)) {throw 'Final source changed'}
foreach($exe in $executables) {if((Digest $exe.path) -ne $exe.sha256) {throw 'Final executable changed'}}
$report=[ordered]@{purpose='Final matched comparison of shared-loop depthwise integration, resolving v1 Medium regression under a single configuration per process and alternating binary order';timestamp=(Get-Date).ToString('o');git_head=(git -C $repo rev-parse HEAD).Trim();source_files=$sources;executables=$executables;cases=$results;execution_seconds=$spent;budget_seconds_per_version=60;comparison_allocation_seconds_per_version=35;warmups_per_case=1;samples_per_case=3;source_and_binaries_stable=$true;limitation='Five cases, three images, one CPU24 configuration; fixed short sampling and sequential processes. Earlier selection/v1 timings are separate experiments and are not pooled.'}
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'final-comparison.json'),($report | ConvertTo-Json -Depth 100))

$ErrorActionPreference = 'Stop'
$repo = (Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
function ReadJson($relative) { Get-Content -LiteralPath (Join-Path $PSScriptRoot $relative) -Raw | ConvertFrom-Json }
function ReadText($relative) { [IO.File]::ReadAllText((Join-Path $PSScriptRoot $relative)) }
function Digest($path) { (Get-FileHash -LiteralPath $path).Hash.ToLowerInvariant() }
$final = ReadJson 'final-comparison.json'
$batch = ReadJson 'batch-selection.json'
$extra = ReadJson 'baseline-extra-execution.json'
$v1Focused = ReadJson 'focused-evidence.json'
$v1Pages = ReadJson 'page-evidence.json'
$diagnosis = @(ReadJson 'rec-diagnosis.json')
$v2Focused = ReadJson 'focused-evidence-v2.json'
$stage = Get-Content -LiteralPath (Join-Path $repo 'docs/reports/windows-x64-2026-10-17-cpu24-stage-analysis.json') -Raw | ConvertFrom-Json
foreach ($source in $final.source_files) {
    if ((Digest (Join-Path $repo $source.path)) -ne $source.sha256) { throw "Source changed: $($source.path)" }
}
foreach ($exe in $final.executables) {
    if ((Digest $exe.path) -ne $exe.sha256) { throw "Executable changed: $($exe.path)" }
}
$summary = @($final.cases | ForEach-Object {
    $old = @($_.baseline.measurement.cases[0].samples_ms | Sort-Object)
    $new = @($_.candidate.measurement.cases[0].samples_ms | Sort-Object)
    [ordered]@{
        model=$_.model;fixture=$_.fixture;execution_order=$_.execution_order
        baseline_median_ms=$old[1];candidate_median_ms=$new[1]
        latency_reduction_percent=100*(1-$new[1]/$old[1])
        observed_ranges_overlap=($new[0] -le $old[-1] -and $old[0] -le $new[-1])
        conclusion=if ($new[-1] -lt $old[0]) {'lower latency in all three samples'} else {'inconclusive with overlapping observed ranges'}
        complete_output_equal=$_.complete_output_equal;retained_bytes_equal=$_.retained_bytes_equal
    }
})
$kernels = @(Get-Content -LiteralPath (Join-Path $PSScriptRoot 'v2-kernel.log') | ForEach-Object {
    if ($_ -match 'short_depthwise_interior (\{.*\})') { $Matches[1] | ConvertFrom-Json }
})
$baselineSeconds = $batch.total_execution_seconds + $extra.total_execution_seconds + ($diagnosis | Where-Object variant -eq 'baseline').wall_seconds + $final.execution_seconds.baseline
$v1Seconds = $v1Focused.total_execution_seconds + $v1Pages.aggregate_page_execution_seconds + ($diagnosis | Where-Object variant -eq 'candidate-v1').wall_seconds
$v2Seconds = $v2Focused.total_execution_seconds + $final.execution_seconds.v2
$budgets = [ordered]@{baseline=$baselineSeconds;rejected_v1=$v1Seconds;retained_v2=$v2Seconds;limit_seconds_per_version=60;accounting='Conservative process wall times including setup; builds and focused correctness checks excluded. Alignment census runs zero inference calls but its whole process is counted.'}
if ($baselineSeconds -ge 60 -or $v1Seconds -ge 60 -or $v2Seconds -ge 60) { throw 'Budget exceeded' }
$newSources = @('src/runtime/nhwc/short_depthwise.rs','src/runtime/nhwc/short_depthwise/tests.rs') | ForEach-Object {
    $absolute = Join-Path $repo $_
    [ordered]@{path=$_;sha256=Digest $absolute;content=[IO.File]::ReadAllText($absolute)}
}
$runners = @('batch-probe.ps1','baseline-extra.ps1','run-focused.ps1','run-pages.ps1','rec-diagnosis.ps1','run-final-comparison.ps1','pointwise-codegen-comparison.py','page-pointwise-codegen-comparison.py','assemble-report.ps1') | ForEach-Object {
    [ordered]@{path=$_;sha256=Digest (Join-Path $PSScriptRoot $_);content=ReadText $_}
}
$patch = @(git -C $repo diff --binary HEAD -- src examples tools Cargo.toml Cargo.lock rust-toolchain.toml) -join "`n"
if ($LASTEXITCODE -ne 0) { throw 'Cannot record source diff' }
$report = [ordered]@{
    schema_version=1
    timestamp=(Get-Date).ToString('o')
    purpose='Retain the best validated optimization among short-depthwise interiors, exact-width batching and packed-weight alignment candidates'
    retained='v2: AVX2/FMA short-depthwise complete-interior tiles sharing the existing checked traversal'
    git_head=$final.git_head
    physical_local_machine=$true
    cpu=$stage.cpu;system=$stage.system;rustc=$stage.rustc
    toolchain='nightly-2026-09-08';target='x86_64-pc-windows-msvc'
    manifest_sha256=$stage.manifest_sha256;assets=$stage.assets
    settings=[ordered]@{
        cpu_context_capacity=24;affinity='ffffff';requested_line_workers=0
        stage_owner_maximum=16;aggregate_rec_pool_capacity=24
        concurrency=1;classification_enabled=$true;recognition_batch_size=1
        capture_ctc_spans=$false;detector_limit=960;adaptive_width=$true
        kernel_policy='auto';layout='auto';fusion=$true
        remaining_manifest_settings=$stage.manifest_settings
        cpu_threads_note='The cpu_threads field in manifest_settings is overridden by the explicit 24-thread context in every page probe.'
    }
    summary=$summary
    final_kernel_cases=$kernels
    final_matched_comparison=$final
    final_kernel_execution=$v2Focused
    performance_execution_seconds=$budgets
    performance_call_counts=[ordered]@{
        baseline=[ordered]@{complete_ocr=52;serial_backbone_prefix=4;note='24 batching selection +8 sparse/mixed controls for v1 +20 final OCR calls; two serial shapes with one warmup and one instrumented prefix each'}
        rejected_v1=[ordered]@{complete_ocr=32;paired_kernel=16;serial_backbone_prefix=4;allocation_census_inference=0}
        retained_v2=[ordered]@{complete_ocr=20;paired_kernel=16;note='Five page cases and two paired kernel shapes; each configuration has one warmup and three measured single calls'}
    }
    separate_rejected_or_diagnostic_experiments=[ordered]@{
        note='No samples in this section are pooled with final measurements. The final experiment changed both integration and process setup, so v1 versus v2 differences are not isolated source effects.'
        batch_selection=$batch
        v1_extra_baseline_execution=$extra
        v1_extra_baseline_pages=@((ReadJson 'baseline-tiny-imgs_1.json'),(ReadJson 'baseline-tiny-imgs_00006737.json'))
        v1_kernel_and_zero_inference_alignment_census=$v1Focused
        v1_pages=$v1Pages
        serial_recognition_diagnosis=$diagnosis
        serial_recognition_note='One warmup and one timed/instrumented prefix per Small width128 and Medium width640; serial synthetic inputs; not the actual dense page widths or a full OCR comparison'
        static_pointwise_test_executables=ReadJson 'pointwise-codegen-comparison.json'
        static_pointwise_page_executables=ReadJson 'page-pointwise-codegen-comparison.json'
        causal_limit='v1 page regression not causally explained; unchanged pointwise instructions exclude a changed instruction-selection explanation in the inspected variants, but do not prove allocator, placement, frequency or host-state causes'
    }
    provenance=[ordered]@{
        baseline_source_files=ReadJson 'baseline/sources.json'
        baseline_tracked_source_patch=ReadText 'baseline/source.patch'
        retained_tracked_source_patch=$patch
        retained_new_source_files=@($newSources)
        baseline_description='HEAD plus the preceding classifier/profile diagnostics and optional batch probe argument; production arithmetic and scheduling precede the new depthwise path'
        rejected_v1_description='Separate whole-layer short-depthwise wrapper; source hashes and executable identities recorded in v1 evidence. Its untracked source content was not snapshotted before v2 refinement.'
        note='Final manifests cover both tracked and nonignored untracked production/benchmark sources. Source/executable identity verified again during evidence assembly; documentation excluded from compiled source identity.'
    }
    validation=[ordered]@{
        focused_correctness_command='cargo test --release --locked --features profiling --lib short_depthwise -- --test-threads=1'
        focused_correctness=[ordered]@{passed=3;ignored=1;failed=0;coverage='five geometries, checked bits, bias/no-bias, fused channel/ReLU/residual, batches, strides, dilation, rectangular kernels, tails, bands, misalignment, guards, malformed storage, independent eligibility oracle'}
        full_library_command='cargo test --release --locked --features profiling --lib -- --test-threads=1'
        full_library_log=ReadText 'v2-full-library-tests.log'
        ordinary_build=[ordered]@{command='cargo build --release --locked --example cpu_owner_probe';exit_code=0;features='default parallel; no profiling'}
        no_default_features=[ordered]@{command='cargo check --release --locked --no-default-features --lib';exit_code=0}
        diff_check=[ordered]@{command='git diff --check';exit_code=0}
        formatting=[ordered]@{command='rustfmt --check --edition 2024 --config skip_children=true examples/cpu_owner_probe.rs examples/cpu_profile.rs src/lines.rs src/orientation.rs src/profile.rs src/profile/tests.rs src/runtime/nhwc.rs src/runtime/nhwc/short_depthwise.rs src/runtime/nhwc/short_depthwise/tests.rs src/runtime/packing.rs';exit_code=0;recursive_check_limitation='The recursive module check finds a pre-existing formatting difference in unchanged src/runtime/nhwc/pointwise/large_channel_tests.rs; no unrelated file was changed.'}
        final_read_only_review='No actionable issues in production integration, unsafe-load eligibility, batch selector or interpretation of final samples'
    }
    runner_sources=@($runners)
    limitations=@(
        'Focused physical Windows AVX2/FMA validation only; no ARM/macOS execution, concurrent throughput or C# full qualification matrix.'
        'Three images, five model/image cases, one CPU24 configuration and three samples per case; fixed short warmup does not establish steady state or statistical confidence.'
        'Sparse Tiny, Small and Medium observed ranges overlap; no improvement/regression claim for those cases. Medium samples drift downward.'
        'Kernel inputs/weights are synthetic and cached, one logical CPU and identity store; kernel gains cannot be directly rescaled to parallel page stages.'
        'Page measurements time complete owned OCR from predecoded pixels, excluding setup/decoding/serialization. Complete output equality is preserved by exact in-process comparisons and cross-version SHA256 of serialized owned results.'
        'Process memory is lifetime private commit including setup; retained capacity equality measures only the reported categories.'
        'Batch selection shares immutable models/context across its two configurations; final comparison uses one configuration per process. Their samples are kept separate.'
        'Allocation census is one allocation sample per model and is storage weighted, not runtime traffic weighted.'
    )
}
$destination = Join-Path $repo 'docs/reports/windows-x64-2026-10-17-depthwise-optimization.json'
[IO.File]::WriteAllText($destination, ($report | ConvertTo-Json -Depth 100), [Text.UTF8Encoding]::new($false))
Write-Output ($budgets | ConvertTo-Json -Compress)
Write-Output "Report bytes: $((Get-Item -LiteralPath $destination).Length)"
